mapper.select:
SELECT tool_job_anchor_json::text FROM alphafrog_agent_run_dag_node
WHERE run_id = #{runId} AND generation = #{generation} AND node_id = #{nodeId}
FOR UPDATE

mapper.update:
WITH reverted AS (
    UPDATE alphafrog_agent_run_dag_node SET
        tool_job_anchor_json = jsonb_build_object(
            'nodePhase','DRAFT',
            'nodeVersion',(tool_job_anchor_json #>> '{nodeVersion}')::bigint + 1),
        updated_at = CURRENT_TIMESTAMP
    WHERE run_id = #{runId} AND generation = #{generation} AND node_id = #{nodeId}
      AND tool_job_anchor_json #>> '{nodePhase}' = 'PREPARING'
      AND (tool_job_anchor_json #>> '{nodeVersion}')::bigint = #{expectedNodeVersion}
      AND tool_job_anchor_json #>> '{operationId}' = #{operationId}
      AND tool_job_anchor_json #>> '{toolCallId}' = #{toolCallId}
      AND tool_job_anchor_json #>> '{attempt}' = #{attempt}::text
      AND tool_job_anchor_json #>> '{requestDigest}' = #{requestDigest}
    RETURNING 1
)
UPDATE alphafrog_agent_run SET
    dag_frontier_json = jsonb_set(jsonb_set(dag_frontier_json,
          ARRAY['nodeStates', #{nodeId}], '"PENDING"'::jsonb),
          '{frontierVersion}', to_jsonb(COALESCE((dag_frontier_json #>> '{frontierVersion}')::bigint,0) + 1)),
    updated_at = CURRENT_TIMESTAMP
WHERE id = #{runId}
  AND (dag_frontier_json #>> '{generation}')::bigint = #{generation}
  AND (dag_frontier_json #>> '{phase}')::text = 'SUSPENDING'
  AND (dag_frontier_json #>> '{frontierVersion}')::bigint = #{expectedFrontierVersion}
  AND (dag_frontier_json #>> '{cancelled}')::boolean IS NOT TRUE
  AND status = 'EXECUTING'
  AND EXISTS(SELECT 1 FROM reverted)

UPDATE alphafrog_agent_run_dag_node dn SET
    tool_job_anchor_json = dn.tool_job_anchor_json || jsonb_build_object(
        'nodePhase','CREATED','taskId',#{taskId}::text,
        'nodeVersion',COALESCE((dn.tool_job_anchor_json #>> '{nodeVersion}')::bigint,0) + 1),
    updated_at = CURRENT_TIMESTAMP
FROM alphafrog_agent_run r
WHERE dn.run_id = r.id AND dn.run_id = #{runId}
  AND dn.generation = #{generation} AND dn.node_id = #{nodeId}
  AND dn.tool_job_anchor_json #>> '{nodePhase}' = 'PREPARING'
  AND (dn.tool_job_anchor_json #>> '{nodeVersion}')::bigint = #{expectedNodeVersion}
  AND dn.tool_job_anchor_json #>> '{operationId}' = #{operationId}
  AND dn.tool_job_anchor_json #>> '{toolCallId}' = #{toolCallId}
  AND dn.tool_job_anchor_json #>> '{attempt}' = #{attempt}::text
  AND dn.tool_job_anchor_json #>> '{requestDigest}' = #{requestDigest}
  AND (r.dag_frontier_json #>> '{generation}')::bigint = dn.generation
  AND CAST(#{taskId} AS text) IS NOT NULL AND btrim(CAST(#{taskId} AS text)) <> ''

UPDATE alphafrog_agent_run_dag_node dn SET
    tool_job_anchor_json = dn.tool_job_anchor_json || jsonb_build_object(
        'nodePhase','TERMINAL','terminalOutcome',#{outcome}::text,
        'terminalError',CAST(#{terminalErrorJson} AS jsonb),
        'nodeVersion',COALESCE((dn.tool_job_anchor_json #>> '{nodeVersion}')::bigint,0) + 1),
    updated_at = CURRENT_TIMESTAMP
FROM alphafrog_agent_run r
WHERE dn.run_id = r.id AND dn.run_id = #{runId}
  AND dn.generation = #{generation} AND dn.node_id = #{nodeId}
  AND dn.tool_job_anchor_json #>> '{nodePhase}' IN ('PREPARING','CREATED','RUNNING')
  AND (dn.tool_job_anchor_json #>> '{nodeVersion}')::bigint = #{expectedNodeVersion}
  AND dn.tool_job_anchor_json #>> '{operationId}' = #{operationId}
  AND dn.tool_job_anchor_json #>> '{toolCallId}' = #{toolCallId}
  AND dn.tool_job_anchor_json #>> '{attempt}' = #{attempt}::text
  AND dn.tool_job_anchor_json #>> '{requestDigest}' = #{requestDigest}
  AND (r.dag_frontier_json #>> '{generation}')::bigint = dn.generation
  AND #{outcome}::text IN ('COMPLETED','FAILED','CANCELED')

UPDATE alphafrog_agent_run_dag_node dn SET
    tool_job_anchor_json = dn.tool_job_anchor_json || jsonb_build_object(
        'nodePhase','RESULT_VALIDATED','resultJson',CAST(#{resultJson} AS jsonb),
        'nodeVersion',COALESCE((dn.tool_job_anchor_json #>> '{nodeVersion}')::bigint,0) + 1),
    updated_at = CURRENT_TIMESTAMP
FROM alphafrog_agent_run r
WHERE dn.run_id = r.id AND dn.run_id = #{runId}
  AND dn.generation = #{generation} AND dn.node_id = #{nodeId}
  AND dn.tool_job_anchor_json #>> '{nodePhase}' = 'TERMINAL'
  AND dn.tool_job_anchor_json #>> '{terminalOutcome}' = 'COMPLETED'
  AND (dn.tool_job_anchor_json #>> '{nodeVersion}')::bigint = #{expectedNodeVersion}
  AND dn.tool_job_anchor_json #>> '{operationId}' = #{operationId}
  AND dn.tool_job_anchor_json #>> '{toolCallId}' = #{toolCallId}
  AND dn.tool_job_anchor_json #>> '{attempt}' = #{attempt}::text
  AND dn.tool_job_anchor_json #>> '{requestDigest}' = #{requestDigest}
  AND (r.dag_frontier_json #>> '{generation}')::bigint = dn.generation
  AND CAST(#{resultJson} AS jsonb) IS NOT NULL
  AND CAST(#{resultJson} AS jsonb) IS DISTINCT FROM 'null'::jsonb
  AND jsonb_typeof(CAST(#{resultJson} AS jsonb)) = 'object'

UPDATE alphafrog_agent_run_dag_node dn SET
    tool_job_anchor_json = dn.tool_job_anchor_json || jsonb_build_object(
        'nodePhase','RELEASED',
        'nodeVersion',COALESCE((dn.tool_job_anchor_json #>> '{nodeVersion}')::bigint,0) + 1),
    updated_at = CURRENT_TIMESTAMP
FROM alphafrog_agent_run r
WHERE dn.run_id = r.id AND dn.run_id = #{runId}
  AND dn.generation = #{generation} AND dn.node_id = #{nodeId}
  AND dn.tool_job_anchor_json #>> '{nodePhase}' = 'USAGE_RECORDED'
  AND (dn.tool_job_anchor_json #>> '{nodeVersion}')::bigint = #{expectedNodeVersion}
  AND dn.tool_job_anchor_json #>> '{operationId}' = #{operationId}
  AND dn.tool_job_anchor_json #>> '{toolCallId}' = #{toolCallId}
  AND dn.tool_job_anchor_json #>> '{attempt}' = #{attempt}::text
  AND dn.tool_job_anchor_json #>> '{requestDigest}' = #{requestDigest}
  AND (r.dag_frontier_json #>> '{generation}')::bigint = dn.generation

UPDATE alphafrog_agent_run_dag_node dn SET
    tool_job_anchor_json = dn.tool_job_anchor_json || jsonb_build_object(
        'nodePhase','FINALIZED',
        'nodeVersion',COALESCE((dn.tool_job_anchor_json #>> '{nodeVersion}')::bigint,0) + 1),
    updated_at = CURRENT_TIMESTAMP
FROM alphafrog_agent_run r
WHERE dn.run_id = r.id AND dn.run_id = #{runId}
  AND dn.generation = #{generation} AND dn.node_id = #{nodeId}
  AND dn.tool_job_anchor_json #>> '{nodePhase}' = 'RELEASED'
  AND (dn.tool_job_anchor_json #>> '{nodeVersion}')::bigint = #{expectedNodeVersion}
  AND dn.tool_job_anchor_json #>> '{operationId}' = #{operationId}
  AND dn.tool_job_anchor_json #>> '{toolCallId}' = #{toolCallId}
  AND dn.tool_job_anchor_json #>> '{attempt}' = #{attempt}::text
  AND dn.tool_job_anchor_json #>> '{requestDigest}' = #{requestDigest}
  AND (r.dag_frontier_json #>> '{generation}')::bigint = dn.generation

mapper.select:
SELECT dag_frontier_json::text FROM alphafrog_agent_run
WHERE id = #{runId}
FOR UPDATE

mapper.update:
UPDATE alphafrog_agent_run_dag_node dn SET
    tool_job_anchor_json = jsonb_build_object(
        'nodePhase','FINALIZED','terminalOutcome','CANCELED',
        'operationId',#{operationId}::text,
        'toolCallId',#{toolCallId}::text,
        'attempt',#{attempt}::int,
        'requestDigest',#{requestDigest}::text,
        'cancelRequestId',#{cancelRequestId}::text,
        'nodeVersion',COALESCE((dn.tool_job_anchor_json #>> '{nodeVersion}')::bigint,0) + 1),
    updated_at = CURRENT_TIMESTAMP
FROM alphafrog_agent_run r
WHERE dn.run_id = r.id
  AND dn.run_id = #{runId}
  AND dn.generation = #{generation}
  AND dn.node_id = #{nodeId}
  AND dn.tool_job_anchor_json #>> '{nodePhase}' = 'PREPARING'
  AND dn.tool_job_anchor_json #>> '{disposition}' = 'CANCELED'
  AND (dn.tool_job_anchor_json #>> '{nodeVersion}')::bigint = #{expectedNodeVersion}
  AND dn.tool_job_anchor_json #>> '{operationId}' = #{operationId}
  AND dn.tool_job_anchor_json #>> '{toolCallId}' = #{toolCallId}
  AND dn.tool_job_anchor_json #>> '{attempt}' = #{attempt}::text
  AND dn.tool_job_anchor_json #>> '{requestDigest}' = #{requestDigest}
  AND (r.dag_frontier_json #>> '{phase}')::text = 'CANCELLING'
  AND (r.dag_frontier_json #>> '{cancelled}')::boolean IS TRUE
  AND r.dag_frontier_json #>> '{cancelRequestId}' = #{cancelRequestId}
  AND (r.dag_frontier_json #>> '{generation}')::bigint = dn.generation

UPDATE alphafrog_agent_run_dag_node dn SET
    tool_job_anchor_json = dn.tool_job_anchor_json || jsonb_build_object(
        'nodePhase','CREATED','taskId',#{taskId}::text,
        'cancelNotfoundRetryCount',0,
        'cancelNextAttemptAt',to_jsonb(CAST(EXTRACT(EPOCH FROM CURRENT_TIMESTAMP) + #{initialBackoffSeconds} AS bigint)),
        'cancelRpcRetryCount',0,
        'nodeVersion',COALESCE((dn.tool_job_anchor_json #>> '{nodeVersion}')::bigint,0) + 1),
    updated_at = CURRENT_TIMESTAMP
FROM alphafrog_agent_run r
WHERE dn.run_id = r.id
  AND dn.run_id = #{runId}
  AND dn.generation = #{generation}
  AND dn.node_id = #{nodeId}
  AND dn.tool_job_anchor_json #>> '{nodePhase}' = 'PREPARING'
  AND dn.tool_job_anchor_json #>> '{disposition}' = 'CANCELED'
  AND (dn.tool_job_anchor_json #>> '{nodeVersion}')::bigint = #{expectedNodeVersion}
  AND dn.tool_job_anchor_json #>> '{operationId}' = #{operationId}
  AND dn.tool_job_anchor_json #>> '{toolCallId}' = #{toolCallId}
  AND dn.tool_job_anchor_json #>> '{attempt}' = #{attempt}::text
  AND dn.tool_job_anchor_json #>> '{requestDigest}' = #{requestDigest}
  AND CAST(#{taskId} AS text) IS NOT NULL AND btrim(CAST(#{taskId} AS text)) <> ''
  AND (r.dag_frontier_json #>> '{phase}')::text = 'CANCELLING'
  AND (r.dag_frontier_json #>> '{cancelled}')::boolean IS TRUE
  AND r.dag_frontier_json #>> '{cancelRequestId}' = #{cancelRequestId}
  AND (r.dag_frontier_json #>> '{generation}')::bigint = dn.generation

UPDATE alphafrog_agent_run SET
    dag_frontier_json = dag_frontier_json - 'reconcilerOwner' - 'reconcilerLeaseUntil',
    updated_at = CURRENT_TIMESTAMP
WHERE id = #{runId}
  AND (dag_frontier_json #>> '{generation}')::bigint = #{generation}
  AND dag_frontier_json #>> '{cancelRequestId}' = #{cancelRequestId}
  AND dag_frontier_json #>> '{reconcilerOwner}' = #{ownerId}
